            "english": "The hedonic treadmill traps individuals in an exhausting loop where fleeting satisfaction evaporates rapidly, necessitating ever-larger material acquisitions.",
            "chinese": "著名的心理学“享乐跑步机效应”，将每一个现代人死死困死在心力交瘁的疲惫怪圈之中——每一次买到心头好所换来的廉价快感转瞬即逝，逼迫人不得不追求更大剂量的物质占有来填补黑洞。",
