            "chinese": "深度深植并沉淀在濒临绝种的偏远原始部落方言土语词汇肌理深处的草木本草分类体系，凝结守护着一套套令现代前沿合成生物制药科学家梦寐以求、无论如何也绝不可承受痛失之痛的无价天然本草民间药典！",
