            "chinese": "某些强权大国妄图通过部署动能反卫星激光武器将浩瀚近地轨道空间恶性军事化、武器化的疯狂玩火行径，极有可能在地球上空引爆令航天界谈虎色变的“凯斯勒多米诺级联太空碎片大风暴”，从而将近地轨道彻底封锁化为人类未来数百年再也无法跨越的致命太空垃圾死亡雷区！",
