            "chinese": "被华尔街季度财报业绩对赌死死卡住脖子的跨国商业传媒财阀，为了压缩运营开支成本，极其冷酷地将原本需要耗费巨资常驻战乱前线的资深海外深度调查记者站全线大面积连根拔起裁撤，转而用毫无营养、充斥着互喷口水嘴炮的廉价演播室脱口秀嘉宾互撕充数！",
