            "english": "Electrical sockets inside science laboratories must never be touched with wet hands to avoid catastrophic electric shock injuries.",
            "chinese": "在理化生实验室开展实验攻关操作期间，绝对严禁用沾满水渍的湿手去直接触碰任何高压仪器插头电源插座，坚决杜绝致命触电恶性事故发生。",
