            "english": "Reporting suspicious strangers wandering along dark campus perimeter fences to security guards prevents potential criminal trespassing.",
            "chinese": "在晚自习放学途经校园昏暗偏僻围墙死角若发现行迹可疑鬼祟闲杂人员，理应第一时间机警报告给门岗值班安保特警叔叔，将安全隐患扼杀在萌芽期。",
            "phonetic": null,
            "note": null
