            "english": "Wrapping savory pork and cabbage dumplings with family members on Chinese New Year's Eve symbolizes wealth, reunion, and auspicious beginnings.",
            "chinese": "在辞旧迎新的除夕年夜饭前夕围坐案板四周同全家人一起包猪肉白菜水饺，不仅寓意着招财进宝更深情象征着阖家团圆与万象更新吉祥如意。",
