            "id": "course-ex-gre-ch3-s15",
            "english": "History is not a cemetery of cold, forgotten bones, but a sacred mirror holding the trembling reflection of our present struggles and future hopes.",
            "chinese": "整部人类历史从来绝非是一座横陈着冰冷死人白骨的荒凉大乱葬岗；它乃是一面高悬在天地苍穹深处的至高明镜——正是在那波光流转的镜面最深处，深情倒映着我们当下所有人正在滚烫经历的苦难挣扎，与我们全人类对未来不灭的星空希望！",
