            "chinese": "托马斯·内格尔名垂青史的经典哲学诘问巨著《成为一只蝙蝠究竟是怎样的一种体验？》以无可辩驳的逻辑向世人证明：第一人称主观“感知体验感受（Phenomenal Consciousness）”，在原理上永远具有无法被任何客观第三人称科学仪器测量与物理还原公式所彻底吞噬消解的认识论鸿沟！",
