            "english": "Literature does not provide passive moral prescriptions; it constructs complex linguistic crucibles wherein contradictory human truths collide in beauty.",
            "chinese": "人类真正伟大的传世传世经典文学，从来绝非是为了向世人廉价兜售几条道貌岸然的道德劝诫小药丸；它乃是人类凭借语言文字的无双造化，在天地之间所亲手构筑起的一座座神圣壮美的复杂审美大熔炉——正是在这里，那些在现实中不可调和的人性悖论、血泪挣扎与深沉大爱，在震撼心灵的艺术大美中璀璨相撞！",
            "phonetic": null,
            "note": null
