            "chinese": "约翰·济慈名留青史的“消极感受力（Negative Capability）”美学至高境界，由衷礼赞一个真正伟大诗人的最高风骨——那就是能够气定神闲、从容安详地长年栖居于扑朔迷离的未解之谜、不确定性与巨大疑云深处，而绝不心急气躁、廉价仓促地去向世俗乞求任何教条确凿的冰冷现成答案！",
