            "english": "False dilemma tactics manipulate audiences by presenting complex multi-factorial issues as binary zero-sum choices while concealing moderate alternatives.",
            "chinese": "令人防不胜防的“假两难推理陷阱（False Dilemma）”，通过在话语修辞中极其险恶地将错综复杂、充满丰富中间地带谱系的复杂社会命题，粗暴极端化阉割为“非黑即白、非此即彼”的二选一零和绝境，以此刻意遮蔽并扼杀一切理性温和的中庸破局可行性方案！",
